WITH oracle_1 AS (WITH event_rows AS (SELECT mktcode,tgtcode,bizdate,ma3>ma30 AND LAG(ma3) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate)<=LAG(ma30) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS matched FROM `newzl`.`hsj_stock_hq_basic_technical`), qualified AS (SELECT mktcode,tgtcode FROM event_rows WHERE bizdate>=DATE_TRUNC('2026-04-14','YEAR') AND bizdate<='2026-04-14' GROUP BY mktcode,tgtcode HAVING SUM(CASE WHEN matched THEN 1 ELSE 0 END)>0) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN qualified q ON q.mktcode=b.mktcode AND q.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14'), branch_1 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_1 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE 1=1 AND q.volume>=0), oracle_2 AS (SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` AS b LEFT JOIN `newzl`.`hsj_stock_hq_basic_technical` AS t ON t.mktcode=b.mktcode AND t.tgtcode=b.tgtcode AND t.bizdate=b.bizdate WHERE b.bizdate='2026-04-14' AND ABS(b.lastPx/10000.0-t.ma20)/NULLIF(ABS(t.ma20),0)<=0.02 AND b.lastPx/10000.0>=t.ma20*0.995), branch_2 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_2 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=0 AND q.volume>=0) SELECT l.mktcode,l.tgtcode,l.bizdate FROM branch_1 l INNER JOIN branch_2 r ON r.mktcode=l.mktcode AND r.tgtcode=l.tgtcode AND r.bizdate=l.bizdate;
